/* ---------- Whole-body anatomy cards, part 2: shoulder girdle, elbow, forearm, wrist and hand, spine and trunk, pelvic floor,
   head, jaw and neck, plus the remaining hip and foot structures. Every structure in the 3D model now opens a card.
   Anatomy follows Gray's Anatomy (Standring, 42nd ed.). Clinical lines cite their source in `src`; where a padel point is
   extrapolated from tennis or other racket sports, the card says so. Group cards (`group`) cover families of small structures
   that share nerve supply and function (for example the muscles of facial expression). ---------- */
SRC.grays = { cite: 'Standring S (ed). Gray\'s Anatomy: The Anatomical Basis of Clinical Practice. 42nd ed. Elsevier; 2020', url: PM('Gray\'s Anatomy anatomical basis of clinical practice Standring') };
SRC.kibler13 = { cite: 'Kibler WB et al. Clinical implications of scapular dyskinesis in shoulder injury: the 2013 consensus statement from the Scapular Summit. Br J Sports Med 2013;47(14):877-885', url: PM('Kibler 2013 scapular dyskinesis consensus statement Scapular Summit') };
SRC.hegedus12 = { cite: 'Hegedus EJ et al. Which physical examination tests provide clinicians with the most value when examining the shoulder? Update of a systematic review with meta-analysis. Br J Sports Med 2012;46(14):964-978', url: PM('Hegedus 2012 physical examination tests shoulder meta-analysis') };
SRC.pieters20 = { cite: 'Pieters L et al. An update of systematic reviews examining the effectiveness of conservative physical therapy interventions for subacromial shoulder pain. J Orthop Sports Phys Ther 2020;50(3):131-141', url: PM('Pieters 2020 conservative physical therapy subacromial shoulder pain systematic reviews') };
SRC.palmer89 = { cite: 'Palmer AK. Triangular fibrocartilage complex lesions: a classification. J Hand Surg Am 1989;14(4):594-606', url: PM('Palmer 1989 triangular fibrocartilage complex lesions classification') };
SRC.morris89 = { cite: 'Morris M, Jobe FW, Perry J, Pink M, Healy BS. Electromyographic analysis of elbow function in tennis players. Am J Sports Med 1989;17(2):241-247', url: PM('Morris 1989 electromyographic analysis elbow function tennis players') };
SRC.blanpied17 = { cite: 'Blanpied PR et al. Neck pain: revision 2017. Clinical practice guidelines linked to the ICF. J Orthop Sports Phys Ther 2017;47(7):A1-A83', url: PM('Blanpied 2017 neck pain clinical practice guidelines revision') };
SRC.jull08 = { cite: 'Jull GA, O\'Leary SP, Falla DL. Clinical assessment of the deep cervical flexor muscles: the craniocervical flexion test. J Manipulative Physiol Ther 2008;31(7):525-533', url: PM('Jull 2008 craniocervical flexion test deep cervical flexor') };
SRC.nice59 = { cite: 'NICE guideline NG59. Low back pain and sciatica in over 16s: assessment and management. National Institute for Health and Care Excellence; 2016, updated 2020', url: 'https://www.nice.org.uk/guidance/ng59' };
SRC.qaseem17 = { cite: 'Qaseem A et al. Noninvasive treatments for acute, subacute, and chronic low back pain: a clinical practice guideline from the American College of Physicians. Ann Intern Med 2017;166(7):514-530', url: PM('Qaseem 2017 noninvasive treatments low back pain American College of Physicians guideline') };
SRC.laslett05 = { cite: 'Laslett M, Aprill CN, McDonald B, Young SB. Diagnosis of sacroiliac joint pain: validity of individual provocation tests and composites of tests. Man Ther 2005;10(3):207-218', url: PM('Laslett 2005 sacroiliac joint pain provocation tests composites') };
SRC.weir15 = { cite: 'Weir A et al. Doha agreement meeting on terminology and definitions in groin pain in athletes. Br J Sports Med 2015;49(12):768-774', url: PM('Weir 2015 Doha agreement groin pain athletes terminology') };
SRC.dumoulin18 = { cite: 'Dumoulin C, Cacciari LP, Hay-Smith EJC. Pelvic floor muscle training versus no treatment, or inactive control treatments, for urinary incontinence in women. Cochrane Database Syst Rev 2018;10:CD005654', url: PM('Dumoulin 2018 pelvic floor muscle training urinary incontinence Cochrane') };
SRC.grimaldi15 = { cite: 'Grimaldi A et al. Gluteal tendinopathy: a review of mechanisms, assessment and management. Sports Med 2015;45(8):1107-1119', url: PM('Grimaldi 2015 gluteal tendinopathy review mechanisms assessment management') };
SRC.hodges96 = { cite: 'Hodges PW, Richardson CA. Inefficient muscular stabilization of the lumbar spine associated with low back pain: a motor control evaluation of transversus abdominis. Spine 1996;21(22):2640-2650', url: PM('Hodges Richardson 1996 transversus abdominis low back pain motor control') };

